self.KB_CONTENT["card:750875"]={"id":"card:750875","ty":"card","sourceId":"750875","title":"『結帳單樹狀資訊查詢』中的『結案碼』為何？","ver":"iGP","topic":"結帳單","keywords":["結帳單","結案","資訊","未結"],"y":"other","answer":"* 分為1.已結案、2.未結案及3.全部，系統預設為【3.全部】，可以用此來選擇結帳單的資料。查詢結果","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
